// [{text, px(RGBA 32×32)}]
export function liveIcons(){
  const raw=zlib.brotliDecompressSync(Buffer.from(BLOB,'base64'));
  return LIVE_TEXTS.map((text,n)=>{ const px=new Uint8ClampedArray(32*32*4); for(let i=0,j=n*3072;i<32*32;i++,j+=3){ px[i*4]=raw[j]; px[i*4+1]=raw[j+1]; px[i*4+2]=raw[j+2]; px[i*4+3]=255; } return {text,px}; });
}
